local CottonGin = {}
local PRODUCTS = {
    raw_cotton = { name = "Surov bombaž", cottonBollCost = 2, time = 1, cost = 14, quality = 30, description = "Surov bombaž iz strokov." },
    ginned_cotton = { name = "Očesan bombaž", cottonBollCost = 3, time = 3, cost = 38, quality = 50, prestige = 1, description = "Očesan bombaž brez semen." },
    carded_cotton = { name = "Česani bombaž", cottonBollCost = 3, oilCost = 1, time = 4, cost = 85, quality = 65, prestige = 2, happiness = 1, description = "Česani bombaž za predenje." },
    combed_cotton = { name = "Glavčan bombaž", cottonBollCost = 4, oilCost = 1, time = 6, cost = 200, quality = 80, prestige = 5, happiness = 2, description = "Glavčan bombaž za fine tkanine." },
    silver_spun_cotton = { name = "Srebrno preden bombaž", cottonBollCost = 5, silverCost = 1, oilCost = 1, time = 9, cost = 460, quality = 92, prestige = 11, happiness = 3, description = "Bombaž s srebrno primesjo za plemiče." },
    royal_grand_cotton = { name = "Kraljevski veliki bombaž", cottonBollCost = 8, goldCost = 1, silverCost = 1, jewelCost = 1, oilCost = 1, time = 14, cost = 1500, quality = 100, prestige = 35, happiness = 8, description = "Veliki kraljevski bombaž z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Bombažarska delavnica", cost = { gold = 270, wood = 130, stone = 200 }, upkeep = 7, qualityBonus = 5 },
    gin_house = { name = "Česalnica", cost = { gold = 900, wood = 250, stone = 400, cotton = 10 }, upkeep = 22, qualityBonus = 18 },
    carding_room = { name = "Česana soba", cost = { gold = 2200, wood = 350, stone = 600, silver = 30, oil = 8 }, upkeep = 55, qualityBonus = 30 },
    royal_cotton_atelier = { name = "Kraljevski atelje bombaža", cost = { gold = 8800, wood = 600, stone = 900, gold = 60, jewel = 20 }, upkeep = 175, qualityBonus = 55, prestigeBonus = 40 },
}
CottonGin.cottonBollStock = 22; CottonGin.oilStock = 12; CottonGin.silverStock = 8; CottonGin.goldStock = 6; CottonGin.jewelStock = 6
CottonGin.productStock = {}; CottonGin.buildings = {}; CottonGin.maker = nil; CottonGin.activeMaking = {}; CottonGin.totalProducts = 0; CottonGin.dayTimer = 0
function CottonGin.init() CottonGin.cottonBollStock=22; CottonGin.oilStock=12; CottonGin.silverStock=8; CottonGin.goldStock=6; CottonGin.jewelStock=6; CottonGin.productStock={}; CottonGin.buildings={}; CottonGin.maker=nil; CottonGin.activeMaking={}; CottonGin.totalProducts=0; CottonGin.dayTimer=0; print("[CottonGin] Royal Cotton Gin System initialized (6 products, 4 buildings)") end
function CottonGin.hireMaker(n,s) s=s or math.random(50,90); local c=490+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CottonGin.maker={name=n or ("Bombažar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Bombažar najet: %s (spretnost: %d)",CottonGin.maker.name,s),"success") end; return true end
function CottonGin.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CottonGin.build(id) local ok,e=CottonGin.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CottonGin.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CottonGin.getQualityBonus() local b=0; for _,bd in ipairs(CottonGin.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CottonGin.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.cottonBollCost and CottonGin.cottonBollStock<(d.cottonBollCost or 0) then return false,"Premalo strokov bombaža" end; if d.oilCost and CottonGin.oilStock<(d.oilCost or 0) then return false,"Premalo olja" end; if d.silverCost and CottonGin.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CottonGin.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CottonGin.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #CottonGin.buildings==0 then return false,"Potrebna delavnica" end; if not CottonGin.maker then return false,"Potreben bombažar" end; return true end
function CottonGin.make(pt,qty) qty=qty or 5; local ok,e=CottonGin.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.cottonBollCost then CottonGin.cottonBollStock=CottonGin.cottonBollStock-d.cottonBollCost*qty end; if d.oilCost then CottonGin.oilStock=CottonGin.oilStock-d.oilCost*qty end; if d.silverCost then CottonGin.silverStock=CottonGin.silverStock-d.silverCost*qty end; if d.goldCost then CottonGin.goldStock=CottonGin.goldStock-d.goldCost*qty end; if d.jewelCost then CottonGin.jewelStock=CottonGin.jewelStock-d.jewelCost*qty end; local t=d.time; if CottonGin.maker then t=math.max(1,t-math.floor(CottonGin.maker.skill/12)) end; table.insert(CottonGin.activeMaking,{id="cotton_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,quality=d.quality or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CottonGin.completeMaking(m) local q=1.0+(CottonGin.getQualityBonus()/100); if CottonGin.maker then q=q+(CottonGin.maker.skill/180) end; q=math.min(2.0,q); CottonGin.productStock[m.productType]=(CottonGin.productStock[m.productType] or 0)+m.quantity; CottonGin.totalProducts=CottonGin.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CottonGin.maker then CottonGin.maker.itemsMade=CottonGin.maker.itemsMade+m.quantity; if math.random()<0.20 then CottonGin.maker.skill=math.min(100,CottonGin.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Bombaž izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"cotton.completed",{productName=m.productName,quality=m.quality}) end end
function CottonGin.update(dt) if not _G.state then return end; CottonGin.dayTimer=CottonGin.dayTimer+dt; if CottonGin.dayTimer>=30 then CottonGin.dayTimer=0; for i=#CottonGin.activeMaking,1,-1 do local m=CottonGin.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CottonGin.completeMaking(m); table.remove(CottonGin.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CottonGin.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CottonGin.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CottonGin.getStats() return {cottonBollStock=CottonGin.cottonBollStock,oilStock=CottonGin.oilStock,silverStock=CottonGin.silverStock,goldStock=CottonGin.goldStock,jewelStock=CottonGin.jewelStock,productStock=CottonGin.productStock,numBuildings=#CottonGin.buildings,hasMaker=CottonGin.maker~=nil,makerName=CottonGin.maker and CottonGin.maker.name or "—",makerSkill=CottonGin.maker and CottonGin.maker.skill or 0,activeMaking=#CottonGin.activeMaking,totalProducts=CottonGin.totalProducts} end
return CottonGin
